            if (((uint16_t)(cpu->a) & 0xFFFFu) == 0u) cpu->p |= NH_P_Z;
            if (((uint16_t)(cpu->a) & 0x8000u) != 0u) cpu->p |= NH_P_N;
            cpu->pbr = 0xC7u;
            cpu->pc = 0x0CFAu;
            if (nh_scpu_expect_next(cpu, 0x063867D0u) != NH_SCPU_EXECUTED)
                return NH_SCPU_STOPPED;
